with with_dims as (select src.id, src.session_id, src.page, src.duration_sec, s.browser, s.device, s.country from web_events src inner join sessions s on src.session_id = s.id), with_dims_web_events as (select src.id, src.session_id, src.duration_sec, src.device, src.country, d.country as session_country, d.browser as session_browser, d.device as session_device from with_dims src left join sessions d on src.session_id = d.id where d.customer_id in (2, 18, 19)), with_dims_web_events_2 as (select src.id, src.session_id, src.device, src.country, src.session_country, b.browser from with_dims_web_events src inner join sessions b on src.session_id = b.id), valid as (select id, session_id, device, country, session_country, browser, trim(device) as clean_device, coalesce(device, 'Unknown') as device_filled from with_dims_web_events_2 where session_country is not null) select browser, count(distinct device) as distinct_devices, count(*) as event_count, count_if(session_country = 'UK') as uk_events, size(collect_set(device)) as num_devices from valid group by 1 order by browser
